// Read counter — answers the landing page with the current state of the daily
// cap. Runs once for all items and emits exactly one item:
//   { used, limit }
// This workflow only reads. The counter file is written by the issue
// collector alone, so a request to this endpoint never spends a slot and a
// hammered endpoint cannot lock stakeholders out.

// The system-wide daily limit from the Lastenheft. The issue collector carries
// the same number as SYSTEM_LIMIT in its guard node. n8n has no shared
// constants between workflows, so the two places have to be changed together —
// a mismatch would make the landing page count towards a limit the mailbox
// does not enforce.
const SYSTEM_LIMIT = 10;

// The counter file the issue collector writes (docs/n8n-setup.md 5.1).
// `quota-state.json` in the same volume belongs to Code a Cuisine. Requires
// NODE_FUNCTION_ALLOW_BUILTIN to include `fs`.
const fs = require('fs');
const QUOTA_FILE = '/home/node/.n8n/join-quota-state.json';

/**
 * Reads the counter file, returning a fresh state when it is missing.
 * @returns {Object} The quota state
 */
function readQuotaState() {
  try {
    return JSON.parse(fs.readFileSync(QUOTA_FILE, 'utf8'));
  } catch (error) {
    return { day: null, system: 0, perSender: {} };
  }
}

/**
 * Starts a fresh counter on the first mail of a new UTC day. The container runs
 * on TZ=UTC, so the day rolls over at UTC midnight. Copied unchanged from the
 * guard node of the issue collector so both workflows see the same day
 * boundary — a state file from yesterday reads as zero here as well.
 * @param {Object} state - The state read from disk
 * @param {Date} now - The current time
 * @returns {Object} The state, reset when the day rolled over
 */
function resetWhenNewDay(state, now) {
  const day = now.toISOString().slice(0, 10);
  const sameDay = Boolean(state) && state.day === day;
  return {
    day,
    system: sameDay ? Number(state.system) || 0 : 0,
    perSender: sameDay && state.perSender ? state.perSender : {},
  };
}

/**
 * The number of requests spent today, capped at the limit. A counter file that
 * somehow holds more must not make the page read `12 of 10`.
 * @param {Object} state - The state for the current day
 * @returns {number} A value between 0 and SYSTEM_LIMIT
 */
function countUsed(state) {
  const used = Number(state.system) || 0;
  return Math.min(Math.max(used, 0), SYSTEM_LIMIT);
}

// --- main -------------------------------------------------------------------
const state = resetWhenNewDay(readQuotaState(), new Date());

return [{ json: { used: countUsed(state), limit: SYSTEM_LIMIT } }];
